DO $seq$ DECLARE tn text; sn text; mx bigint; lv bigint; BEGIN
FOREACH tn IN ARRAY ARRAY['businesses', 'business_menu_categories', 'business_menu_items', 'business_menu_option_groups', 'business_menu_option_items', 'menu_option_groups', 'menu_option_choices', 'business_catering_categories', 'business_catering_items', 'business_catering_option_groups', 'business_catering_option_choices', 'business_catering_settings', 'business_gallery_images', 'business_instagram_posts', 'business_sections', 'business_website_banners'] LOOP
 sn := pg_get_serial_sequence('public.' || quote_ident(tn), 'id');
 IF sn IS NOT NULL THEN
  EXECUTE format('SELECT max(id) FROM public.%I', tn) INTO mx;
  EXECUTE format('SELECT last_value FROM %s', sn) INTO lv;
  IF mx IS NOT NULL THEN PERFORM setval(sn::regclass, greatest(mx,lv), true); END IF;
 END IF;
END LOOP;
END $seq$;

